"""Write the markdown page for the three part score from three_part_score_results (run three_part_score.py first)."""
from grid_tools import *
r = json.load(open("three_part_score_results%s.json" % SUF))
rule = ("0 and 4 and 8 open north. 1 and 5 and 9 open east. 2 and 6 open south. 3 and 7 open west." if ZERO_NORTH
        else "1 and 5 and 9 open north. 2 and 6 open east. 3 and 7 open south. 4 and 8 and 0 open west.")
def line(n, e): return "%d. %s: score %d (largest region %d + longest walk %d + door points %d)" % (n, e["prime"], e["score"], e["largest_region"], e["longest"], e["door_points"])
L = []; A = L.append
A("# Three part score ranking: primes ranked by largest region plus longest walk plus door points"); A("")
A("> **About this page:** One AI model (Claude) wrote this page on 25 November 2026. The author of this repository proposed the score and the chatbot wrote the programs and ran the counts. The counts are measurements from the programs three_part_score.py and three_part_score_page.py in the folder boring-things/research-program-files/prime-mazes-scripts. The page proves nothing about primes. No other person has reviewed the page yet."); A("")
A("## The score"); A("")
A("Each digit of a prime opens one door of a room and the digits fill a square grid row by row starting at the top left room. This page uses the version of the door rule where " + ("0 opens north" if ZERO_NORTH else "1 opens north") + ": " + rule); A("")
A("The three part score adds three numbers."); A("")
A("- **Largest region:** the most rooms that are joined together by open doors.")
A("- **Longest walk:** the most rooms one line can pass through without entering any room twice.")
A("- **Door points:** picture a player who walks around the outside of the grid and may open a door from outside at any spot on the outer wall. The player earns 1 point for each spot where the player can enter and then walk through joined rooms to the opposite side of the grid and leave there. A spot on the top wall needs a path to the bottom row and a spot on the left wall needs a path to the right column. A corner room has two spots because a corner room touches two outer walls."); A("")
A("A grid of 3 by 3 rooms has 12 spots on the outer wall (3 on each side) so the door points stop at 12. A grid of 2 by 2 rooms has 8 spots and a grid of 4 by 4 rooms has 16 spots."); A("")
A("## The highest possible score"); A("")
A("One hallway through every room that reaches all four sides earns the most: every room for the largest region plus every room for the longest walk plus every spot on the outer wall for the door points."); A("")
A("- 2 by 2 rooms: 4 + 4 + 8 = 16")
A("- 3 by 3 rooms: 9 + 9 + 12 = 30 (the program checked all 262144 door patterns and the highest score found is %d)" % r["grid3"]["highest_score_any_door_pattern"])
A("- 4 by 4 rooms: 16 + 16 + 16 = 48")
A("- 5 by 5 rooms: 25 + 25 + 20 = 70"); A("")
A("No grid can beat these totals because the largest region and the longest walk cannot hold more rooms than the grid has and the door points cannot exceed the number of spots on the outer wall."); A("")
A("Separate hallways score lower than one full hallway because separate hallways are short. Four hallways side by side on a grid of 4 by 4 rooms earn 4 + 4 + 8 = 16 because the 4 top spots and the 4 bottom spots each lead across while no left spot leads to the right side."); A("")
g3 = r["grid3"]; sc = g3["score_counts"]; top = max(int(v) for v in sc)
A("## Grid of 3 by 3 rooms: all %d primes with 9 digits" % g3["primes"]); A("")
A("### How many primes earn each score"); A("")
for v, c in sc.items(): A("- Score %s: %d primes (%.3f%%)" % (v, c, 100 * c / g3["primes"]))
A("")
A("### Rank 1: the %d primes that tie at the highest score of %d" % (sc[str(top)], top)); A("")
A("Every one of these primes makes one hallway through all 9 rooms. The 40 smallest are listed here in order."); A("")
A("A wider group of %d primes earns all 12 door points because every room is joined into one region even when no single line passes through all 9 rooms." % g3["door_point_counts"]["12"]); A("")
for i, e in enumerate(g3["first_primes_for_each_score"][str(top)], 1): A(line(i, e))
A("")
A("### The smallest primes for the next scores"); A("")
for v in [x for x in sc if int(x) < top][:8]:
    A("Score %s (%d primes). The 5 smallest:" % (v, sc[v])); A("")
    for e in g3["first_primes_for_each_score"][v][:5]: A("- %s (largest region %d + longest walk %d + door points %d)" % (e["prime"], e["largest_region"], e["longest"], e["door_points"]))
    A("")
for b in r["larger_grids"]:
    k = b["grid"]; bt = r["built"][str(k)]
    A("## Grid of %d by %d rooms: the 25 highest scores among %d random primes with %d digits" % (k, k, b["samples"], k * k)); A("")
    A("The primes with %d digits are too many to test one by one so this list ranks a random sample. The highest possible score is %d and no prime in the sample reached that score." % (k * k, 2 * k * k + 4 * k) if b["top_25"][0]["score"] < 2 * k * k + 4 * k else "The highest possible score is %d." % (2 * k * k + 4 * k)); A("")
    for i, e in enumerate(b["top_25"], 1): A(line(i, e))
    A("")
    A("A prime built on purpose to make one hallway through all %d rooms reaches the highest possible score:" % (k * k)); A("")
    A("- %s: score %d (largest region %d + longest walk %d + door points %d)" % (bt["prime"], bt["score"], bt["largest_region"], bt["longest"], bt["door_points"])); A("")
A("## Larger grids: primes built on purpose"); A("")
for k in ("6", "8", "10"):
    bt = r["built"][k]; A("- %s by %s rooms: score %d (largest region %d + longest walk %d + door points %d) for the prime %s" % (k, k, bt["score"], bt["largest_region"], bt["longest"], bt["door_points"], bt["prime"]))
A("")
g2 = r["grid2"]; hist = {}
for e in g2: hist[e["score"]] = hist.get(e["score"], 0) + 1
A("## Grid of 2 by 2 rooms: all %d primes with 4 digits ranked" % len(g2)); A("")
A("### How many primes earn each score"); A("")
for v in sorted(hist, reverse=True): A("- Score %d: %d primes" % (v, hist[v]))
A("")
A("### The full ranking"); A("")
A("Primes with the same score are listed from smallest to largest."); A("")
for i, e in enumerate(g2, 1): A(line(i, e))
A("")
A("## Weak points"); A("")
A("- Thousands of primes tie at each score so the order inside a tie is just smallest prime first.")
A("- The lists for grids of 4 by 4 rooms and 5 by 5 rooms rank a random sample and not every prime of that size.")
A("- The score is one choice among many. On this score a full hallway always wins because the largest region and the longest walk both grow with the same hallway.")
A("- The ranking uses one version of the door rule and a different choice of which number opens north gives a different ranking."); A("")
A("## Related pages"); A("")
A("- [maze-test-zero-north.md](maze-test-zero-north.md) reports the full maze test under the version of the rule where 0 opens north.")
A("- [maze-test-findings.md](maze-test-findings.md) reports the full maze test under the version where 1 opens north.")
A("- [maze-animation.html](maze-animation.html) draws any of these primes one room at a time.")
open("three-part-score-ranking%s.md" % DASH, "w").write("\n".join(L) + "\n"); print(len(L))
